/** The 18 ids frozen in v1. Exported so a test can assert the set never drifts. */
export const V1_FROZEN_IDS = Object.freeze(Object.keys(V1_LEGACY_DEFINITIONS).sort());

/**
 * The warning that must accompany every legacy response wherever it is shown.
 * One string, one place — so print, copy, PDF and the item panel cannot drift.
 */
export const V1_LEGACY_WARNING =
  "Legacy PennSync response set—do not copy this code. Answer the official item "
  + "again from the wording in your EMR.";

/** @param {string} definitionId */
export function v1Definition(definitionId) {
  return V1_LEGACY_DEFINITIONS[String(definitionId || "").toLowerCase()] || null;
}

/**
 * The label a legacy value was answered under, or "" when the value is not one
 * the frozen set knows. Display-only: never returns something carryable.
 */
export function v1LabelFor(definitionId, value) {
  const def = v1Definition(definitionId);
  if (!def) return "";
  const hit = def.options.find((o) => o.value === value || String(o.value) === String(value));
  return hit ? hit.label : "";
}
